import{_ as e,o as p,c as r,a2 as a}from"./chunks/framework.DPTp4bo7.js";const _=JSON.parse('{"title":"完美均匀有理数输出","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/perfectly-uniform-rational-output"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/perfectly-uniform-rational-output"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/perfectly-uniform-rational-output"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/perfectly-uniform-rational-output"}]]},"headers":[],"relativePath":"zh/perfectly-uniform-rational-output.md","filePath":"zh/page-8DMQhNnwNc2wWjxNQYCtX4.md"}'),o={name:"zh/perfectly-uniform-rational-output.md"};function n(i,t,l,s,f,c){return p(),r("div",null,[...t[0]||(t[0]=[a('<div class="logistics-content"><span class="logistics-source-anchor" id="完美均匀有理数输出" aria-hidden="true"></span><h1 id="完美均匀有理数输出" tabindex="-1">完美均匀有理数输出 <a class="header-anchor" href="#完美均匀有理数输出" aria-label="Permalink to &quot;完美均匀有理数输出&quot;">​</a></h1><blockquote><p>源页面 ID：<code>8DMQhNnwNc2wWjxNQYCtX4</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=8DMQhNnwNc2wWjxNQYCtX4" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>参见<a href="/endfield-skydoc/zh/theory-of-perfectly-uniform-rational-output-devices">完美均匀有理数输出器相关理论</a></p><p>目前通用实现方案有以下几种</p><p>@xyIvneu_ 的闰年规则</p><p>@Cipolla_ 的引入加法闰年规则改进版</p><p>@桜夜天華 的回流式完美均匀输出</p><p>各方法均使用了以下思路，目前认为该思路由闰年规则首次提出</p><p>对于任意序列x，若操作f的结果f(x)在x为完美均匀序列时为完美均匀序列，则多个f_i(x)嵌套依旧为完美均匀序列；通过将目标x_i多步改写为f_i(x_(i-1))使最终x_0容易实现，即可使用x_0和f_i输出x_i</p><p>以下是我们目前找到的可行的f</p><p>取补操作：将序列中0-1互换， f(x) = 1 - x</p><p>取商操作：将序列中1每隔n个保留一个，其他全部删去，f(x) = x / n</p><p>加法操作：对每一位加1或者说加n（n为整数，相当于多次+1），f(x) = n + x</p><p>对于各操作的实现：</p><p><span class="mark-red">待补充成果节点截图</span></p><p>假设 x_i = 最简分数 a / b，b = a * q + r即q = b // a, r = b % a</p><p><strong>标准闰年规则：</strong></p><p>x_i = a / b = (1 - r / b) / q = (1 - x_(i-2) ) / q</p><p>x_0 = [1]</p><p><strong>闰年规则改进：</strong></p><p>x_i = a / b =(1 - r / b) / q 或 (1 + r&#39; / b) / q&#39;，使用搜索算法取展开较短式</p><p>前一种情况与标准闰年规则一致</p><p>后一种情况r&#39; = a-r,q&#39; = q + 1; x_(i-2) = r&#39; / b</p><p>x_0 = [1]</p><p><strong>回流式：</strong></p><p>x_i = (A + x_(i - 2)) / B</p><p>限制A的可能取值后，使用搜索算法取所有可能展开中的最短</p><p>x_0 = x_n，表示与输出完全相等的回流作为输入，这使得结构末尾必然是二分</p><p>该展开不适用于2^n*3^m为分母的分数，但是这类分数可以使用其他方式构造</p></div>',1)])])}const h=e(o,[["render",n]]);export{_ as __pageData,h as default};
